#include "closed_transpose_arithmetic.hpp"
struct MTWitness {CFPoly factor;bool infinity=false;unsigned long parameter=0;MCycle residual;G image;std::vector<CTFiber> fibers;std::vector<std::string> rejections;};
Poly<F> mt_restrict(const EBPoly& f,const F& m,const F& t){Poly<F> x{F(0),F(1)},y{t,m},out;for(auto& [e,c]:f.terms){Poly<F> term{F(CFPoly{c})};for(int i=0;i<e[0];++i)term=term*x;for(int j=0;j<e[1];++j)term=term*y;out=out+term;}return out;}
G mt_point(const MMap& map,const CFPoly& factor,const CFPoly& qx,const CFPoly& qy,bool infinity,MTWitness& witness){
    auto saved=modulus,saved_source=GBSource::modulus;witness.factor=factor;witness.infinity=infinity;unsigned long d=unsigned(map.den.degree()),bound=(2*d+8)*(2*d+8)*(2*d+8)*(2*d+8)+32;require(prime>mpz_class(bound),"moving transpose line schedule below characteristic");
    for(unsigned long a=0;a<=bound;++a){try{
        modulus=factor;F z(CFPoly{Z(0),Z(1)}),tx=ct_eval(qx,z),ty=ct_eval(qy,z),m=infinity?ty:F(CFPoly{Z(mpz_class(a))}),t=infinity?F(CFPoly{Z(mpz_class(a))}):ty-m*tx;auto restriction=mt_restrict(map.f,m,t);Poly<F> residual;
        if(infinity){require(restriction.degree()==3,"moving infinity line transverse chart");residual=restriction.monic();}else{require(restriction.degree()==4,"moving finite line affine degree4");residual=restriction.exact(Poly<F>{-tx,F(1)}).monic();require(residual.degree()==3,"moving finite residual degree3");}
        GBSource::modulus=factor;std::vector<GBSource> uc;for(auto& c:residual.c)uc.emplace_back(c.a);MAlgebra algebra(factor.degree(),GBP(uc),GBP{GBSource(0),GBSource(1)},GBP{GBSource(t.a),GBSource(m.a)});auto cycle=algebra.cycle(map.f);modulus=saved;GBSource::modulus=saved_source;std::vector<CTFiber> fibers;G value=ct_closed(map,cycle.u,cycle.x,cycle.y,fibers);for(auto& f:fibers)require(f.u.degree()==9,"moving residual meets transpose boundary");witness.parameter=a;witness.residual=cycle;witness.fibers=std::move(fibers);witness.image=value;return value;
    }catch(const std::exception& e){modulus=saved;GBSource::modulus=saved_source;witness.rejections.push_back(std::to_string(a)+":"+e.what());}}
    throw std::runtime_error("moving transpose line schedule exhausted");
}
G mt_normalized(const MMap& map,const CFPoly& u,const CFPoly& x,const CFPoly& y,const G& aref,std::vector<MTWitness>& witnesses){
    require(cm_curve(map.f,u,x,y).degree()<0,"moving closed input quartic");std::vector<CFPoly> factors;ct_factor(u,factors);CFPoly replay{Z(1)};G total;for(auto& factor:factors){ct_irreducible(factor);replay=replay*factor;MTWitness w;auto a=mt_point(map,factor,x%factor,y%factor,false,w);total=total.add(aref.times(factor.degree()).add(a.neg()));witnesses.push_back(w);}require(replay==u.monic(),"moving input factor multiplicity replay");return total;
}
void mt_emit(const MTWitness& w){std::cout<<"{\"factor\":";cf_emit_poly(w.factor);std::cout<<",\"infinity\":"<<(w.infinity?"true":"false")<<",\"line_parameter\":"<<w.parameter<<",\"rejections\":[";for(size_t i=0;i<w.rejections.size();++i)std::cout<<(i?",":"")<<std::quoted(w.rejections[i]);std::cout<<"],\"residual_cycle\":";cm_emit_cycle(w.residual);std::cout<<",\"source_image\":";tr_emit_g(w.image);std::cout<<",\"transpose_factors\":[";for(size_t i=0;i<w.fibers.size();++i){if(i)std::cout<<',';ct_emit(w.fibers[i]);}std::cout<<"]}";}
int main(int argc,char** argv){try{
    require(argc==5,"usage: moving_transpose study global bridge formal");std::string root=argv[1];initialize_cover(read_json(root+"/inputs/p192-d7-prym.json"));Level2Input input;auto global=read_json(argv[2]),bridge=read_json(argv[3]),formal=read_json(argv[4]),model=read_json(root+"/evidence/p192-d7-kernel3-plane-quartic.json"),points=read_json(root+"/evidence/destination-relations-v2/result.json");EBPoly f;for(auto& row:model.at("terms").arr){auto e=row.at("exponents");f.add({e.arr[0].integer(),e.arr[1].integer()},Z(mpz_class(row.at("coefficient").scalar)));}MMap map(global,f);auto point=[&](int i){auto& p=points.at("points").arr[size_t(i)];return std::array<Z,2>{Z(mpz_class(p.at("x").scalar)),Z(mpz_class(p.at("y").scalar))};};auto ref=point(0);CFPoly linear{Z(0),Z(1)};MTWitness rw;auto aref=mt_point(map,linear,CFPoly{ref[0]},CFPoly{ref[1]},false,rw);auto direct_ref=tr_fiber(map,ref[0],ref[1]).reduced;std::vector<MTWitness> witnesses{rw};int rational_checks=0,source_checks=0;
    std::vector<int> ids{0,1,2,3,223,224,225};int final=points.at("split_fibers").arr[0].at("point_indices").arr[0].integer();if(std::find(ids.begin(),ids.end(),final)==ids.end())ids.push_back(final);
    for(int id:ids){auto p=point(id);MTWitness w;G aq=mt_point(map,linear,CFPoly{p[0]},CFPoly{p[1]},false,w),value=aref.add(aq.neg());auto expected=tr_fiber(map,p[0],p[1]).reduced.add(direct_ref.neg());require(value==expected,"moving/direct rational transpose equality");witnesses.push_back(w);++rational_checks;std::cerr<<"moving rational point "<<id<<" line="<<w.parameter<<" passed\n";}
    G reference;for(auto& id:formal.at("seed_indices").arr){auto p=point(id.integer());std::vector<MTWitness> ws;reference=reference.add(mt_normalized(map,linear,CFPoly{p[0]},CFPoly{p[1]},aref,ws));witnesses.insert(witnesses.end(),ws.begin(),ws.end());}
    std::vector<G> source_results;for(auto& row:bridge.at("images").arr){std::vector<MTWitness> ws;auto value=mt_normalized(map,pc_read_poly(row.at("target_U")),linear,pc_read_poly(row.at("target_V")),aref,ws);G source=cm_source(row);value=value.add(reference.times(source.u.degree()).neg());require(value==source.times(3),"moving closed psi phi composition3");require(!(value.add(source)==source.times(3)),"moving changed composition rejects");source_results.push_back(value);witnesses.insert(witnesses.end(),ws.begin(),ws.end());++source_checks;std::cerr<<"moving closed source fixture "<<source_checks-1<<" passed\n";}
    std::vector<Z> infinity_coeff(5,Z(0));for(auto& [e,c]:f.terms)if(e[0]+e[1]==4)infinity_coeff[size_t(e[1])]=infinity_coeff[size_t(e[1])]+c;CFPoly inf(infinity_coeff);require(inf.degree()==4,"no missing vertical infinity chart");std::vector<CFPoly> infinity_factors;ct_factor(inf,infinity_factors);CFPoly infinity_replay{Z(1)};G infinity_image;for(auto& factor:infinity_factors){ct_irreducible(factor);infinity_replay=infinity_replay*factor;MTWitness w;auto a=mt_point(map,factor,CFPoly{Z(1)},linear,true,w);infinity_image=infinity_image.add(aref.times(factor.degree()).add(a.neg()));witnesses.push_back(w);std::cerr<<"infinity closed point degree="<<factor.degree()<<" line="<<w.parameter<<" passed\n";}require(infinity_replay==inf.monic(),"all infinity factors and multiplicities");G finite_image;for(auto& id:points.at("split_fibers").arr[0].at("point_indices").arr){auto p=point(id.integer());finite_image=finite_image.add(tr_fiber(map,p[0],p[1]).reduced.add(direct_ref.neg()));}require(infinity_image==finite_image,"infinity and finite hyperplane transpose equality");
    std::cout<<"{\"scope\":\"P192-kernel3-line-moving-closed-projective-transpose\",\"standing\":\"producer-unverified\",\"rational_agreement_checks\":"<<rational_checks<<",\"source_composition3_checks\":"<<source_checks<<",\"infinity_polynomial\":";cf_emit_poly(inf);std::cout<<",\"infinity_closed_points_with_multiplicity\":"<<infinity_factors.size()<<",\"infinity_hyperplane_checked\":true,\"infinity_image\":";tr_emit_g(infinity_image);std::cout<<",\"source_results\":[";for(size_t i=0;i<source_results.size();++i){if(i)std::cout<<',';tr_emit_g(source_results[i]);}std::cout<<"],\"moving_witnesses\":[";for(size_t i=0;i<witnesses.size();++i){if(i)std::cout<<',';mt_emit(witnesses[i]);}std::cout<<"],\"universal_avoidance_bound_independently_checked\":false}\n";
}catch(const std::exception& e){std::cerr<<"REJECT "<<e.what()<<'\n';return 1;}}
